#include "vehicle_upgrades.hpp"
#include "legacy_ui/car_config.hpp"
namespace ofo {
void apply_selected_upgrades(VehicleConfig&c,const Resources&r,const std::vector<std::string>&parts){if(parts.empty())return;auto path="cars/car_"+std::to_string(c.id);auto base=car_configuration(r,path),up=car_configuration(r,path,parts);auto value=[](const Json&j,const char*k,float fallback){if(!j.contains(k)||!j.at(k).is_number())return fallback;float v=j.at(k);if(!std::isfinite(v))throw std::runtime_error("Nonfinite upgraded physical parameter");return v;};
 float physical_delta=value(up,"cb.Mass",0)-value(base,"cb.Mass",0)+4*(value(up,"ct.Mass",0)-value(base,"ct.Mass",0));float previous_mass=c.mass;c.mass=std::max(1.f,c.mass+physical_delta);c.authored_mass+=physical_delta;c.inertia=c.inertia*(c.mass/previous_mass);
 c.engine_inertia=value(up,"ce.InertiaEngine",c.engine_inertia);c.shaft_inertia=value(up,"ce.InertiaDriveShaft",c.shaft_inertia);c.engine_friction=value(up,"ce.EngineFriction",c.engine_friction);c.clutch_torque=value(up,"cg.ClutchTorque",c.clutch_torque);c.clutch_release=value(up,"cg.ClutchReleaseTime",c.clutch_release);c.gear_shift=value(up,"cg.GearShiftTime",c.gear_shift);c.clutch_engage=value(up,"cg.ClutchEngageTime",c.clutch_engage);
 c.idle_rpm=value(up,"ce.IdleRpm",c.idle_rpm);c.steering_limit=value(up,"cb.SteeringLimit",c.steering_limit);c.steering_reduction=value(up,"cb.SteeringReduction",c.steering_reduction);
 c.engine_torque=value(up,"ce.TorqueMax",c.engine_torque);c.final_ratio=value(up,"cg.EndRatio",c.final_ratio);c.brake_torque=value(up,"cb.BrakeTorque",c.brake_torque);c.handbrake=value(up,"cb.HandBrakeTorque",c.handbrake);c.front_drive=value(up,"cb.FrontTraction",c.front_drive);c.downforce=value(up,"cb.DownForceConst",c.downforce);c.nitro_g=value(up,"ce.NitroAcceleration",c.nitro_g);c.nitro_capacity=value(up,"ce.NitroStorage",c.nitro_capacity);if(up.contains("cb.AeroDrag"))c.drag=vector3(up.at("cb.AeroDrag"));
 auto gear_count=int(value(up,"cg.NumGears",float(c.ratios.size())));if(gear_count<1||gear_count>8)throw std::runtime_error("Upgraded gearbox count");std::vector<float>ratios;for(int i=1;i<=gear_count;i++){auto key="cg.Gear"+std::to_string(i);float ratio=up.value(key,i<=int(c.ratios.size())?c.ratios[i-1]:1.f);if(!std::isfinite(ratio)||ratio<=0)throw std::runtime_error("Upgraded gear ratio");ratios.push_back(ratio);}c.ratios=ratios;
 auto component=[](const Json&j,const char*k,const char*index,float fallback){auto it=j.find(k);if(it==j.end()||!it->is_object()||!it->contains(index)||!(*it)[index].is_number())return fallback;return (*it)[index].get<float>();};
 c.reverse_ratio=component(up,"cg.GearRRatio","2",c.reverse_ratio);
 int samples=int(value(up,"ce.TorqueCurveParams",float(c.torque_curve.size())));std::vector<std::pair<float,float>>curve;for(int i=0;i<samples;i++){auto key="ce.Torque"+(i<10?std::string("0"):std::string())+std::to_string(i);if(!up.contains(key))throw std::runtime_error("Missing upgraded active torque sample");auto v=up.at(key);float rpm=v.at("1"),torque=v.at("2");if(!std::isfinite(rpm)||!std::isfinite(torque)||torque<0||(!curve.empty()&&rpm<=curve.back().first))throw std::runtime_error("Invalid upgraded torque sample");curve.push_back({rpm,torque});}if(curve.size()<2)throw std::runtime_error("Invalid upgraded torque curve");c.torque_curve=curve;c.max_rpm=curve.back().first;

 for(auto&w:c.wheels){w.mass=value(up,"ct.Mass",w.mass);w.radius=value(up,"ct.Radius",w.radius);w.inertia_factor=value(up,"ct.MomentOfInertia",w.inertia_factor);}for(auto axis:{std::make_pair("ct.LocalDynamicsXFriction",&c.tire_dynamics.lateral),std::make_pair("ct.LocalDynamicsZFriction",&c.tire_dynamics.longitudinal)}){float stock=component(base,axis.first,"1",1),selected=component(up,axis.first,"1",stock);if(stock>0)*axis.second*=selected/stock;}
 c.tire_dynamics.optimal_slip_ratio=value(up,"ct.LocalDynamicsOptimalSlipRatio",c.tire_dynamics.optimal_slip_ratio);c.tire_dynamics.optimal_slip_angle=value(up,"ct.LocalDynamicsOptimalSlipAngle",c.tire_dynamics.optimal_slip_angle);
 for(int i=0;i<4;i++){auto&w=c.wheels[i];std::string side=i<2?"cs.Front":"cs.Rear";w.rest=value(up,(side+"RestLength").c_str(),w.rest);w.min=value(up,(side+"MinLength").c_str(),w.min);w.max=value(up,(side+"MaxLength").c_str(),w.max);float quarter=value(up,"cb.Mass",c.authored_mass)*.25f;float compression=value(up,(side+"DefaultCompression").c_str(),0);if(compression>0){w.k=quarter*9.81f/compression;float critical=2*std::sqrt(w.k*quarter);w.bump=critical*value(up,(side+"BumpDamp").c_str(),.35f);w.rebound=critical*value(up,(side+"ReboundDamp").c_str(),.4f);}}

 auto rollbar=c.provenance.value("handling",Json::object()).value("rollbar",Json::array({.1f,.1f}));for(int i=0;i<2;i++)rollbar[i]=value(up,i?"cs.RearRollBarStiffness":"cs.FrontRollBarStiffness",rollbar.at(i).get<float>());c.provenance["handling"]["rollbar"]=rollbar;
 c.provenance["selected_upgrades"]=parts;c.provenance["upgrade_source"]="original Settings/MaxSettings interpolation; no menu display mass";c.provenance["upgrade_mass_delta"]=physical_delta;
}
}
